// Generates the province tables for Go and TypeScript from data/provinces.json.
// Run: node scripts/gen-regions.mjs
// CI runs this script and fails if the generated files change.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const { provinces } = JSON.parse(readFileSync(join(root, "data/provinces.json"), "utf8"));
const codes = Object.keys(provinces).sort();
const header = "Code generated by scripts/gen-regions.mjs. DO NOT EDIT.";

const goLines = codes.map((c) => `\t${JSON.stringify(c)}: ${JSON.stringify(provinces[c])},`);
const goSrc = `// ${header}

package region

// Provinces maps a 2-digit Kemendagri province code to the province name.
var Provinces = map[string]string{
${goLines.join("\n")}
}
`;

const tsLines = codes.map((c) => `  ${JSON.stringify(c)}: ${JSON.stringify(provinces[c])},`);
const tsSrc = `// ${header}

/** Maps a 2-digit Kemendagri province code to the province name. */
export const provinces: Readonly<Record<string, string>> = {
${tsLines.join("\n")}
};
`;

writeFileSync(join(root, "internal/region/provinces_gen.go"), goSrc);
writeFileSync(join(root, "ts/src/internal/provinces.gen.ts"), tsSrc);
console.log(`Generated ${codes.length} provinces.`);
